// Cyrillic directly in the name-entry field.
//
// The field keeps the typed text as UTF-16 fullwidth Latin ("Ｉｔｄｘ...", padded with U+3000) in heap memory, and
// draws/converts it with the game's own (EFIGS) character table. That table already has the Russian/Ukrainian
// common letters where our font has them; the Ukrainian-only letters (і ї є ґ) sit at indices of rare kanji, so
// those are written as the kanji (entrychars.tsv, generated by build_mod.py).
// Names.cs hands the game the Latin letter of each Cyrillic key; here, right after, the Latin letters of the
// current entry are replaced in the field with the Cyrillic ones. On confirm the game encodes the field itself.
using System;
using System.Collections.Generic;
using System.IO;
using System.Runtime.InteropServices;
using System.Text;
using System.Threading;

namespace P5RUkr
{
    public static unsafe class Entry
    {
        static Dictionary<char, char> _map;
        static long _addr;               // start of the field found last time
        static volatile bool _dirty;

        public static void Start(string modDir)
        {
            var path = Path.Combine(modDir, "entrychars.tsv");
            if (!File.Exists(path)) { Mod.Log("entry: entrychars.tsv missing"); return; }
            _map = new Dictionary<char, char>();
            foreach (var line in File.ReadAllLines(path, Encoding.UTF8))
            {
                var t = line.Split('\t');
                if (t.Length == 2 && t[0].Length == 1 && t[1].Length == 1) _map[t[0][0]] = t[1][0];
            }
            new Thread(Loop) { IsBackground = true }.Start();
        }

        public static void Touch() => _dirty = true;

        static void Loop()
        {
            while (true)
            {
                Thread.Sleep(40);
                if (!_dirty) continue;
                _dirty = false;
                try { Fix(); } catch (Exception e) { Mod.Log("entry: " + e.Message); }
            }
        }

        static char Full(char c) => c == ' ' ? '　' : c >= '!' && c <= '~' ? (char)(0xFF01 + c - '!') : c;

        static void Fix()
        {
            var (lat, chr) = Names.CurrentSegment();
            if (lat.Length == 0 || lat.Length != chr.Length) return;
            bool any = false;
            foreach (var c in chr) if (_map.ContainsKey(char.ToLower(c)) || _map.ContainsKey(c)) { any = true; break; }
            if (!any) return;

            if (_addr == 0 || !Matches(_addr, lat, chr))
            {
                _addr = Find(lat);
                if (_addr == 0) return;
                Mod.Log($"entry: field at {_addr:X}");
            }
            char* p = (char*)_addr;
            for (int k = 0; k < lat.Length; k++)
            {
                char g = p[k];
                if (char.ToLower(g) != Full(char.ToLower(lat[k])) && g != Full(char.ToUpper(lat[k]))) continue;
                bool upper = g >= 'Ａ' && g <= 'Ｚ';
                char c = upper ? char.ToUpper(chr[k]) : char.ToLower(chr[k]);
                if (_map.TryGetValue(c, out var w)) p[k] = w;
            }
        }

        // the field still holds this entry: every position is the fullwidth Latin letter or what we wrote for it
        static bool Matches(long addr, string lat, string chr)
        {
            try
            {
                char* p = (char*)addr;
                for (int k = 0; k < lat.Length; k++)
                {
                    char g = p[k];
                    if (g == Full(char.ToLower(lat[k])) || g == Full(char.ToUpper(lat[k]))) continue;
                    if (_map.TryGetValue(char.ToLower(chr[k]), out var a) && g == a) continue;
                    if (_map.TryGetValue(char.ToUpper(chr[k]), out var b) && g == b) continue;
                    return false;
                }
                return true;
            }
            catch { return false; }
        }

        // search private read-write memory for the fullwidth text (first letter in either case)
        static long Find(string lat)
        {
            var variants = new List<byte[]>();
            foreach (var first in new[] { char.ToUpper(lat[0]), char.ToLower(lat[0]) })
            {
                var sb = new StringBuilder();
                sb.Append(Full(first));
                for (int k = 1; k < lat.Length; k++) sb.Append(Full(lat[k]));
                variants.Add(Encoding.Unicode.GetBytes(sb.ToString()));
            }
            for (long a = 0x10000; a < 0x7FFFFFFF0000;)
            {
                if (VirtualQuery((IntPtr)a, out var m, (UIntPtr)sizeof(MBI)) == UIntPtr.Zero) break;
                long rs = (long)m.BaseAddress, sz = (long)m.RegionSize;
                if (m.State == 0x1000 && m.Type == 0x20000 && (m.Protect & 0xFF) == 0x04 && sz < 0x20000000)
                {
                    var span = new ReadOnlySpan<byte>((void*)rs, (int)sz);
                    foreach (var v in variants)
                    {
                        int at = span.IndexOf(v);
                        while (at >= 0)
                        {
                            long hit = rs + at;
                            // the field is padded with U+3000 / NUL right after the text
                            char next = *(char*)(hit + v.Length);
                            if (hit % 2 == 0 && (next == '　' || next == '\0')) return hit;
                            int nxt = span.Slice(at + 2).IndexOf(v);
                            at = nxt < 0 ? -1 : at + 2 + nxt;
                        }
                    }
                }
                a = rs + sz;
            }
            return 0;
        }

        [StructLayout(LayoutKind.Sequential)]
        struct MBI
        {
            public IntPtr BaseAddress, AllocationBase;
            public uint AllocationProtect;
            public IntPtr RegionSize;
            public uint State, Protect, Type;
        }

        [DllImport("kernel32.dll")] static extern UIntPtr VirtualQuery(IntPtr a, out MBI m, UIntPtr len);
    }
}
